import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.Collections;import java.util.StringTokenizer;import java.util.List;public class TestClass {static class DSU {int[] parent;int[] size;public DSU(int n) {parent = new int[n + 1];size = new int[n + 1];for (int i = 1; i <= n; i++) {parent[i] = i;size[i] = 1;}}public int find(int i) {if (parent[i] == i) return i;return parent[i] = find(parent[i]);}public void union(int i, int j) {int rootI = find(i);int rootJ = find(j);if (rootI != rootJ) {if (size[rootI] < size[rootJ]) {int temp = rootI;rootI = rootJ;rootJ = temp;}parent[rootJ] = rootI;size[rootI] += size[rootJ];}}}public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;StringTokenizer st = new StringTokenizer(line);int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());int k = Integer.parseInt(st.nextToken());DSU dsu = new DSU(n);for (int i = 0; i < m; i++) {String edgeLine = br.readLine();if (edgeLine == null) break;st = new StringTokenizer(edgeLine);int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());dsu.union(u, v);}List<Integer> sizes = new ArrayList<Integer>();for (int i = 1; i <= n; i++) {if (dsu.parent[i] == i) {sizes.add(dsu.size[i]);}}Collections.sort(sizes, Collections.reverseOrder());long totalSize = 0;int limit = Math.min(k + 1, sizes.size());for (int i = 0; i < limit; i++) {totalSize += sizes.get(i);}System.out.println(totalSize);}}